     4|export default function VictoryOverlay({
     5|  show, winner, isDraw, lastHash, onNewGame, onReplay, onExport, moveCount,
     6|}) {
     7|  const [particlesCreated, setParticlesCreated] = useState(false)
     8|  const containerRef = useState(null)
     9|
    10|  const winnerName = winner === 1 ? '黑方' : winner === 2 ? '白方' : ''
    11|  const displayTitle = isDraw ? '平局' : `${winnerName}胜`
    12|  const shortHash = lastHash ? lastHash.substring(0, 24) + '...' : '—'
    13|
    14|  // 粒子效果
    15|  useEffect(() => {
    16|    if (show && !particlesCreated && !isDraw && winner) {
    17|      // 延迟创建粒子，配合动画时间
    18|      const timer = setTimeout(() => {
    19|        const container = document.querySelector('.victory-particles-container')
    20|        if (container) {
    21|          createParticles(container, {
    22|            count: 30,
    23|            colors: winner === 1 
    24|              ? ['var(--accent-primary)', '#7c3aed', '#00d4ff']
    25|              : ['var(--accent-primary)', '#00ff88', '#00d4ff'],
    26|            sizeRange: [3, 8],
    27|            duration: 1200,
    28|            spread: 150,
    29|          })
    30|          setParticlesCreated(true)
    31|        }
    32|      }, 400)
    33|
    34|      return () => clearTimeout(timer)
    35|    }
    36|  }, [show, winner, isDraw, particlesCreated])
    37|
    38|  // 重置粒子状态
    39|  useEffect(() => {
    40|    if (!show) {
    41|      setParticlesCreated(false)
    42|    }
    43|  }, [show])
    44|
    45|  return (
    46|    <div
    47|      className={`
    48|        absolute inset-0 flex flex-col items-center justify-center
    49|        bg-paper/92 backdrop-blur-sm transition-opacity duration-500
    50|        ${show ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}
    51|      `}
    52|    >
    53|      {/* 粒子容器 */}
    54|      <div className="victory-particles-container absolute inset-0 overflow-hidden pointer-events-none" />
    55|
    56|      {/* 胜利标题 - 增强动画 */}
    57|      <div
    58|        className="font-calligraphy text-5xl text-ink tracking-[12px] relative"
    59|        style={{ 
    60|          animation: show ? 'victory-appear 0.6s cubic-bezier(0.34,1.56,0.64,1) forwards' : 'none',
    61|          transform: 'scale(3)',
    62|          opacity: 0,
    63|        }}
    64|      >
    65|        {displayTitle}
    66|        {/* 发光效果 */}
    67|        {show && (
    68|          <div 
    69|            className="absolute inset-0 font-calligraphy text-5xl tracking-[12px]"
    70|            style={{
    71|              color: 'var(--accent-primary)',
    72|              filter: 'blur(20px)',
    73|              opacity: 0.4,
    74|              animation: 'glow-pulse 2s ease-in-out infinite',
    75|            }}
    76|          >
    77|            {displayTitle}
    78|          </div>
    79|        )}
    80|      </div>
    81|
    82|      {/* 获胜棋子 - 增强动画 */}
    83|      {!isDraw && winner && (
    84|        <div
    85|          className={`w-12 h-12 rounded-full my-4 ${winner === 1 ? 'stone-black' : 'stone-white'} relative`}
    86|          style={{ 
    87|            animation: show ? 'victory-spin 0.8s cubic-bezier(0.34,1.56,0.64,1) 0.2s both' : 'none',
    88|          }}
    89|        >
    90|          {/* 棋子光环 */}
    91|          {show && (
    92|            <div 
    93|              className="absolute -inset-2 rounded-full animate-breathe"
    94|              style={{
    95|                background: 'transparent',
    96|                border: `2px solid ${winner === 1 ? 'var(--accent-secondary)' : 'var(--accent-primary)'}`,
    97|                opacity: 0.6,
    98|              }}
    99|            />
   100|          )}
   101|        </div>
   102|      )}
   103|
   104|      {/* 哈希值 */}
   105|      <div 
   106|        className="font-mono text-[10px] text-ink-faint tracking-wide mt-2 px-3 py-1.5 border border-paper-dark bg-white/50"
   107|        style={{
   108|          animation: show ? 'fade-scale-in 0.4s cubic-bezier(0.4,0,0.2,1) 0.5s both' : 'none',
   109|        }}
   110|      >
   111|        GAME HASH: {shortHash}
   112|      </div>
   113|
   114|      {/* 移动计数 */}
   115|      <div 
   116|        className="font-mono text-[9px] text-ink-faint tracking-widest mt-2"
   117|        style={{
   118|          animation: show ? 'slide-in-up 0.3s ease 0.6s both' : 'none',
   119|        }}
   120|      >
   121|        {moveCount} MOVES
   122|      </div>
   123|
   124|      {/* 按钮组 - 交错入场 */}
   125|      <div className="flex gap-3 mt-5">
