   144|            }}
   145|          >
   146|            回放
   147|          </button>
   148|        )}
   149|        {onExport && moveCount > 0 && (
   150|          <button
   151|            type="button"
   152|            onClick={onExport}
   153|            className="px-8 py-3 font-serif-sc text-sm tracking-[4px] transition-colors hover-glow"
   154|            style={{
   155|              background: 'var(--bg-surface)',
   156|              border: '1px solid var(--border-color)',
   157|              color: 'var(--text-secondary)',
   158|              animation: show ? 'slide-in-up 0.3s ease 1.0s both' : 'none',
   159|            }}
   160|          >
   161|            导出棋谱
   162|          </button>
   163|        )}
   164|      </div>
   165|    </div>
   166|  )
